namespace DeepSeekChat.Models;

/// <summary>
/// A chat message as stored in the history.
/// </summary>
public sealed class ChatMessageItem
{
    /// <summary>
    /// Gets or sets sender.
    /// </summary>
    public string Sender { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets message.
    /// </summary>
    public string Message { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets created at.
    /// </summary>
    public DateTime CreatedAt { get; set; }

    /// <summary>
    /// Gets or sets whether the message was generated by the AI.
    /// </summary>
    public bool IsAi { get; set; }

    /// <summary>
    /// Gets or sets a value indicating whether the message is an error notice; such messages are not sent back to the model.
    /// </summary>
    public bool IsError { get; set; }

    /// <summary>
    /// Paths to the stored copies of photos shown as thumbnails.
    /// </summary>
    public List<string> ImagePaths { get; set; } = new();
}
